-- Lasso stores: the research list of 2026-11-01 (docs/research/lasso-stores.csv, 143 stores: 129 live with Lasso, 8 closed
-- that day, 6 that left Lasso) put into lasso_stores (0019), so the board's "Lasso checkout" filter (worker/src/lasso.mjs)
-- knows them without a run of the discovery job. Additive and safe to run on every workflow run: a store already in the
-- table (saved by lasso.mjs, or by this file before) keeps every value it has; only its empty aliases are filled. lasso.mjs
-- checks these stores again like any store it saved: one that leaves Lasso gets confidence '' and leaves the filter.
-- aliases: the store's other domains ("a.com b.com"), from the research. lasso.mjs neither reads nor writes it.
ALTER TABLE lasso_stores ADD COLUMN aliases TEXT;
ON CONFLICT(store) DO UPDATE SET aliases = excluded.aliases WHERE lasso_stores.aliases IS NULL AND excluded.aliases IS NOT NULL;
